import{_ as o,o as e,c as i,ag as s}from"./chunks/framework.Aev9KvMf.js";const p=JSON.parse('{"title":"白名单例外第二类：实用工具站导航（MuscleWiki 等）","description":"","frontmatter":{},"headers":[],"relativePath":"project/adr/0019-tool-sites.md","filePath":"project/adr/0019-tool-sites.md"}'),r={name:"project/adr/0019-tool-sites.md"};function a(l,t,n,u,c,_){return e(),i("div",null,[...t[0]||(t[0]=[s('<h1 id="白名单例外第二类-实用工具站导航-musclewiki-等" tabindex="-1">白名单例外第二类：实用工具站导航（MuscleWiki 等） <a class="header-anchor" href="#白名单例外第二类-实用工具站导航-musclewiki-等" aria-label="Permalink to &quot;白名单例外第二类：实用工具站导航（MuscleWiki 等）&quot;">​</a></h1><p>用户要求收录&quot;类似 MuscleWiki 的好用日用软件网站&quot;。MuscleWiki、USDA FoodData Central、NutritionFacts.org 均为境外工具站，与 ADR 0002&quot;不推荐商业品牌&quot;红线冲突。沿用 ADR 0018 开创的显式例外机制，设立<strong>第二类例外：实用工具站导航</strong>，规则：</p><ol><li><strong>双阵营物理分区</strong>：页面分&quot;官方阵营&quot;（白名单内：辟谣平台、科普中国、中国天气网、国家智慧教育平台、国家图书馆——本次一并收录，均已浏览器核验）与&quot;延伸阵营&quot;（境外工具站），官方永远在前。</li><li><strong>收录门槛</strong>：延伸阵营仅收<strong>免费核心功能、无佣金无利益关联、口碑与实用性强</strong>的工具站；付费墙产品（如 Examine.com）不收。</li><li><strong>配对义务</strong>：每条延伸工具必须注明与官方内容的配对关系（如 MuscleWiki × 身体活动指南：官方定&quot;练多少&quot;，工具站补&quot;动作怎么做&quot;）；境外数据标准明确标注&quot;不等于中国官方推荐量&quot;。</li><li><strong>可下架</strong>：出现商业化变质（加佣金、强广告）即移除。</li></ol><p>首批：官方 5 站 + 延伸 3 站（MuscleWiki 中文界面、USDA FDC、NutritionFacts.org）。同页还完成&quot;辟谣/科普/天气/教育/图书馆&quot;五个官方高价值工具站的首次收录。</p>',4)])])}const q=o(r,[["render",a]]);export{p as __pageData,q as default};
